using Invoicing.Legacy;

namespace Invoicing;

/// <summary>Exports an invoice as a PDF byte stream.</summary>
public sealed class PdfExporter
{
    private static readonly Func<string, IEnumerable<string>, byte[]> RenderPdf = CreateRenderer();

    public byte[] Export(Invoice invoice)
    {
        var lines = new List<string>();
        foreach (var line in invoice.Lines)
            lines.Add($"{line.Description}: {line.NetAmount}");
        // TODO: include the billing address block in the header
        return RenderPdf($"Invoice {invoice.Number}", lines);
    }

    private static Func<string, IEnumerable<string>, byte[]> CreateRenderer()
    {
        var method = typeof(RenderApiV1).GetMethod(
            "ToPdf",
            new[] { typeof(string), typeof(IEnumerable<string>) })
            ?? throw new MissingMethodException(typeof(RenderApiV1).FullName, "ToPdf");

        return (Func<string, IEnumerable<string>, byte[]>)Delegate.CreateDelegate(
            typeof(Func<string, IEnumerable<string>, byte[]>),
            method);
    }
}
